<?php
declare(strict_types=1);require_once __DIR__.'/UserStorage.php';
final class Auth {
    public function __construct(private readonly array $config){if(session_status()!==PHP_SESSION_ACTIVE){session_name('zystem_wf');$secure=(($_SERVER['HTTPS']??'')==='on');session_set_cookie_params(['httponly'=>true,'samesite'=>'Lax','secure'=>$secure]);session_start();}}
    public function user():?array{return isset($_SESSION['zystem_user'])&&is_array($_SESSION['zystem_user'])?$_SESSION['zystem_user']:null;}
    public function guest():array{session_regenerate_id(true);return $_SESSION['zystem_user']=['id'=>0,'email'=>null,'username'=>null,'display_name'=>'Usuário temporário','role'=>'guest','temporary'=>true];}
    public function requireUser():array{$user=$this->user();if(!$user)$user=$this->guest();return $user;}
    public function register(string $name,string $email,string $password):array{$name=trim($name);$email=strtolower(trim($email));if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($password)<8)throw new InvalidArgumentException('Informe nome, e-mail válido e senha com pelo menos 8 caracteres.');$pdo=Database::connection($this->config);$count=(int)$pdo->query('SELECT COUNT(*) FROM users')->fetchColumn();$username='user_'.bin2hex(random_bytes(4));$stmt=$pdo->prepare('INSERT INTO users(email,username,password_hash,display_name,role) VALUES(?,?,?,?,?)');try{$stmt->execute([$email,$username,password_hash($password,PASSWORD_DEFAULT),$name,$count===0?'admin':'student']);UserStorage::home($this->config,(int)$pdo->lastInsertId());}catch(PDOException $e){if((int)($e->errorInfo[1]??0)===1062)throw new RuntimeException('Este e-mail já está cadastrado.');throw $e;}return $this->login($email,$password);}
    public function login(string $identifier,string $password):array{$identifier=trim($identifier);$pdo=Database::connection($this->config);$stmt=$pdo->prepare('SELECT id,email,username,display_name,role,password_hash FROM users WHERE LOWER(email)=LOWER(?) OR LOWER(username)=LOWER(?) LIMIT 1');$stmt->execute([$identifier,$identifier]);$row=$stmt->fetch();if(!$row||!password_verify($password,$row['password_hash']))throw new RuntimeException('Usuário/e-mail ou senha inválidos.');unset($row['password_hash']);session_regenerate_id(true);$_SESSION['zystem_user']=$row;return $row;}
    public function changePassword(array $user,string $current,string $next):array{if((int)($user['id']??0)<1)throw new RuntimeException('Sessões temporárias não possuem senha.');if(strlen($next)<8)throw new InvalidArgumentException('A nova senha deve ter pelo menos 8 caracteres.');$pdo=Database::connection($this->config);$q=$pdo->prepare('SELECT password_hash FROM users WHERE id=?');$q->execute([(int)$user['id']]);$hash=$q->fetchColumn();if(!is_string($hash)||!password_verify($current,$hash))throw new RuntimeException('Senha atual incorreta.');$u=$pdo->prepare('UPDATE users SET password_hash=? WHERE id=?');$u->execute([password_hash($next,PASSWORD_DEFAULT),(int)$user['id']]);return ['changed'=>true];}
    public function logout():bool{$_SESSION=[];if(ini_get('session.use_cookies')){$p=session_get_cookie_params();setcookie(session_name(),'',time()-42000,$p['path'],$p['domain'],$p['secure'],$p['httponly']);}session_destroy();return true;}
}
?>
